const createMotif = function createMotif(config, random) {
  if (!Array.isArray(config.motif) || !config.motif.length || config.motif.some(item =>
    !Number.isFinite(item.radius) || item.radius <= 0 || !Number.isFinite(item.sweep) ||
    item.sweep === 0 || Math.abs(item.sweep) > Math.PI * 2 ||
    item.radius * Math.abs(item.sweep) < config.stepLength)) throw new Error('Invalid turn motif');
  let index = config.motifRandomStart ? Math.floor(random() * config.motif.length) : 0;
  const mirror = config.motifMirror && random() < 0.5 ? -1 : 1;
  let remaining = Math.abs(config.motif[index].sweep);
  let interrupted = false;
  return {
    peek(maxLength = config.stepLength) {
      const item = config.motif[index];
      const length = Math.min(maxLength, remaining * item.radius);
      return { index, radius: item.radius, length,
        turn: Math.sign(item.sweep) * mirror * length / item.radius,
        remainingLength: remaining * item.radius, interrupted };
    },
    consume(length) {
      remaining -= length / config.motif[index].radius;
      interrupted = false;
      if (remaining <= 1e-9) {
        index = (index + 1) % config.motif.length;
        remaining = Math.abs(config.motif[index].sweep);
      }
    },
    interrupt() {
      // Restart the interrupted section once there is room, without advancing it.
      if (!interrupted) remaining = Math.abs(config.motif[index].sweep);
      interrupted = true;
    },
  };
};
const createPortals = function createPortals(width, height, padding = 0) {
  const wrap = (value, size) => ((value % size) + size) % size;
  const canonical = p => ({ x: wrap(p.x, width), y: wrap(p.y, height) });
  const cross = (a,b,c) => (b.x-a.x)*(c.y-a.y)-(b.y-a.y)*(c.x-a.x);
  function pointDistance(p,a,b) {
    const dx=b.x-a.x, dy=b.y-a.y;
    const t=Math.max(0,Math.min(1,((p.x-a.x)*dx+(p.y-a.y)*dy)/(dx*dx+dy*dy || 1)));
    return Math.hypot(p.x-a.x-t*dx,p.y-a.y-t*dy);
  }
  function segmentDistance(a,b,c,d) {
    if(cross(a,b,c)*cross(a,b,d)<0 && cross(c,d,a)*cross(c,d,b)<0) return 0;
    return Math.min(pointDistance(a,c,d),pointDistance(b,c,d),pointDistance(c,a,b),pointDistance(d,a,b));
  }
  function collides(a,b,c,d,gap) {
    // Enumerate only periodic images whose expanded bounding boxes can overlap.
    const x0=Math.ceil((Math.min(a.x,b.x)-gap-Math.max(c.x,d.x))/width);
    const x1=Math.floor((Math.max(a.x,b.x)+gap-Math.min(c.x,d.x))/width);
    const y0=Math.ceil((Math.min(a.y,b.y)-gap-Math.max(c.y,d.y))/height);
    const y1=Math.floor((Math.max(a.y,b.y)+gap-Math.min(c.y,d.y))/height);
    for(let x=x0;x<=x1;x++) for(let y=y0;y<=y1;y++) {
      const shift=p=>({x:p.x+x*width,y:p.y+y*height});
      if(segmentDistance(a,b,shift(c),shift(d))<gap) return true;
    }
    return false;
  }
  function split(arc, from, to, pointAt) {
    if(to<=from) return [];
    // Separate at direction extrema first, making each coordinate monotonic.
    const stops=[from,to];
    if(Math.abs(arc.turn)>1e-10) {
      const angleAt=s=>arc.heading+arc.turn*(s-arc.from)/(arc.to-arc.from);
      const lo=Math.min(angleAt(from),angleAt(to)), hi=Math.max(angleAt(from),angleAt(to));
      for(let k=Math.ceil(lo/(Math.PI/2));k<=Math.floor(hi/(Math.PI/2));k++) {
        const s=arc.from+(k*Math.PI/2-arc.heading)/arc.turn*(arc.to-arc.from);
        if(s>from+1e-9 && s<to-1e-9) stops.push(s);
      }
    }
    stops.sort((a,b)=>a-b);
    const cuts=[from,to];
    for(let i=1;i<stops.length;i++) {
      const lo=stops[i-1],hi=stops[i];
      for(const [axis,size] of [['x',width],['y',height]]) {
        const a=pointAt(arc,lo)[axis],b=pointAt(arc,hi)[axis];
        if(Math.abs(a-b)<1e-10) continue;
        for(let k=Math.ceil(Math.min(a,b)/size);k<=Math.floor(Math.max(a,b)/size);k++) {
          const edge=k*size;
          let left=lo,right=hi;
          for(let j=0;j<45;j++) {
            const mid=(left+right)/2;
            if((pointAt(arc,mid)[axis]<edge)===(a<b)) left=mid; else right=mid;
          }
          const s=(left+right)/2;
          if(s>from+1e-8 && s<to-1e-8) cuts.push(s);
        }
      }
    }
    cuts.sort((a,b)=>a-b);
    const unique=cuts.filter((s,i)=>i===0 || s-cuts[i-1]>1e-7);
    const pieces=[];
    for(let i=1;i<unique.length;i++) {
      const a=unique[i-1],b=unique[i],mid=pointAt(arc,(a+b)/2);
      const dx=-Math.floor(mid.x/width)*width,dy=-Math.floor(mid.y/height)*height;
      const shift=p=>({x:p.x+dx,y:p.y+dy});
      pieces.push({from:a,to:b,start:shift(pointAt(arc,a)),end:shift(pointAt(arc,b)),dx,dy});
    }
    return pieces;
  }
  function fragments(arc, piece, pointAt) {
    const points=[piece.start,piece.end];
    // Arc excursion from its chord is bounded by radius * (1-cos(angle/2)).
    const angle=Math.abs(arc.turn)*(piece.to-piece.from)/(arc.to-arc.from);
    const sagitta=Math.abs(arc.turn)<1e-10?0:(arc.to-arc.from)/Math.abs(arc.turn)*(1-Math.cos(angle/2));
    const pad=padding+sagitta;
    const xs=[0],ys=[0];
    if(Math.min(...points.map(p=>p.x))<pad) xs.push(width);
    if(Math.max(...points.map(p=>p.x))>width-pad) xs.push(-width);
    if(Math.min(...points.map(p=>p.y))<pad) ys.push(height);
    if(Math.max(...points.map(p=>p.y))>height-pad) ys.push(-height);
    return xs.flatMap(x=>ys.filter(y=>x!==0 || y!==0).map(y=>({
      ...piece,start:{x:piece.start.x+x,y:piece.start.y+y},end:{x:piece.end.x+x,y:piece.end.y+y},
    })));
  }
  return { canonical, collides, split, fragments };
};
const createTrail = function createTrail(config) {
  const { width, height, margin, stepLength: step, minGap, strokeWidth } = config;
  if (![width, height, margin, step, minGap, strokeWidth].every(Number.isFinite) ||
      step <= 0 || minGap < 0 || strokeWidth <= 0 || margin < strokeWidth / 2 ||
      width <= margin * 2 || height <= margin * 2 ||
      ![config.searchBudget, config.attempts].every(n => Number.isInteger(n) && n > 0) ||
      !Array.isArray(config.radii) || config.radii.length !== 2 ||
      !config.radii.every(r => Number.isFinite(r) && r > 0)) {
    throw new Error("Invalid walker configuration");
  }
  const padding = strokeWidth / 2 + 4 * config.blur + 4;
  const portals = config.wrapEdges ? createPortals(width, height, padding) : null;
  let state = config.seed >>> 0;
  function random() {
    state += 0x6D2B79F5;
    let t = Math.imul(state ^ state >>> 15, 1 | state);
    t ^= t + Math.imul(t ^ t >>> 7, 61 | t);
    return ((t ^ t >>> 14) >>> 0) / 4294967296;
  }
  const clamp = (x, a, b) => Math.max(a, Math.min(b, x));
  const clearance = minGap + strokeWidth;
  const neighbors = Math.ceil(clearance / step) + 2;
  // Validate the motif before including its curvature in collision tolerances.
  if (config.motifEnabled) createMotif(config, () => 0.5);
  const maxTurn = step / Math.min(...config.radii,
    ...(config.motifEnabled ? config.motif.map(item => item.radius) : []));
  // Bound the exempt local neighborhood to less than a quarter turn.
  if (maxTurn * (neighbors + 1) >= Math.PI / 2) {
    throw new Error("Radii too small for the stroke width, gap, and step length");
  }
  if (portals && Math.min(width, height) <= 2 * ((neighbors + 1) * step + clearance)) {
    throw new Error("Portal viewport too small for the local stroke neighborhood");
  }
  const subdivisions = 4;
  const error = step * maxTurn / (8 * subdivisions ** 2);
  const distanceToSegment = (p, a, b) => {
    const dx = b.x - a.x, dy = b.y - a.y;
    const t = clamp(((p.x - a.x) * dx + (p.y - a.y) * dy) / (dx * dx + dy * dy || 1), 0, 1);
    return Math.hypot(p.x - a.x - t * dx, p.y - a.y - t * dy);
  };
  const cross = (a, b, c) => (b.x - a.x) * (c.y - a.y) - (b.y - a.y) * (c.x - a.x);
  function distance(a, b, c, d) {
    if (cross(a, b, c) * cross(a, b, d) < 0 && cross(c, d, a) * cross(c, d, b) < 0) return 0;
    return Math.min(distanceToSegment(a, c, d), distanceToSegment(b, c, d),
      distanceToSegment(c, a, b), distanceToSegment(d, a, b));
  }
  function propose(p, heading, turn, arcLength = step) {
    const points = [p];
    for (let i = 1; i <= subdivisions; i++) {
      const f = i / subdivisions;
      // Stable circular-arc evaluation, including nearly straight steps.
      const half = turn * f / 2;
      const length = arcLength * f * (Math.abs(half) < 1e-10 ? 1 : Math.sin(half) / half);
      points.push({ x: p.x + length * Math.cos(heading + half), y: p.y + length * Math.sin(heading + half) });
    }
    return { points, turn, length: arcLength, end: points.at(-1) };
  }
  function valid(candidate, mesh, arcIndex) {
    if (!portals) for (const p of candidate.points) {
      if (p.x < margin + error || p.x > width - margin - error ||
          p.y < margin + error || p.y > height - margin - error) return false;
    }
    for (let i = 1; i < candidate.points.length; i++) {
      const a = candidate.points[i - 1], b = candidate.points[i];
      for (const segment of mesh) {
        if (arcIndex - segment.arc < neighbors) continue;
        const gap = clearance + 2 * error;
        if (portals) {
          if (portals.collides(a, b, segment.a, segment.b, gap)) return false;
          continue;
        }
        if (Math.max(a.x, b.x) + gap < Math.min(segment.a.x, segment.b.x) ||
            Math.min(a.x, b.x) - gap > Math.max(segment.a.x, segment.b.x) ||
            Math.max(a.y, b.y) + gap < Math.min(segment.a.y, segment.b.y) ||
            Math.min(a.y, b.y) - gap > Math.max(segment.a.y, segment.b.y)) continue;
        if (distance(a, b, segment.a, segment.b) < gap) return false;
      }
    }
    return true;
  }

  if (![config.trailLength, config.tailFadeLength, config.turnEase].every(n => Number.isFinite(n) && n > 0) ||
      config.tailFadeLength >= config.trailLength || !Number.isFinite(config.straightChance) ||
      config.straightChance < 0 || config.straightChance > 1) throw new Error("Invalid trail settings");
  const turns = config.radii.flatMap(radius => [step / radius, -step / radius]);
  let p = { x: width * (0.3 + random() * 0.4), y: height * (0.3 + random() * 0.4) };
  let heading = random() * Math.PI * 2;
  let turn = turns[Math.floor(random() * turns.length)];
  let target = turn, straightLeft = 0, nextChoice = 10;
  let arcs = [], mesh = [], endDistance = 0, head = 0, blocked = false, index = 0;
  const motif = config.motifEnabled ? createMotif(config,random) : null;
  const approach = targetTurn => turn + clamp(targetTurn - turn, -config.turnEase, config.turnEase);

  function options() {
